target.css:
:root {
  --paper: #fffdf8;
  --ink: #273044;
  --muted: #737b8b;
  --line: #e9e1d7;
  --plum: #6d466f;
  --plum-soft: #eee2ef;
  --blush: #f4d5ce;
  --amber: #e7b65d;
  --mint: #cfe4d5;
  --white: #ffffff;
}

.blend-card {
  box-sizing: border-box;
  width: 500px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--paper);
  color: var(--ink);
}

.topline,
.formula-heading,
.card-footer,
.maker,
.accord,
.notes li,
button {
  display: flex;
  align-items: center;
}

.topline {
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0;
  color: var(--plum);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.2px;
  text-transform: uppercase;
}

.batch {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--plum-soft);
  color: var(--plum);
  font-size: 10px;
  font-weight: 800;
}

.formula-heading {
  justify-content: space-between;
  padding: 13px 0 12px;
}

.formula-heading h1 {
  margin: 0 0 3px;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -0.6px;
}

.formula-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.status {
  padding: 6px 9px;
  border: 1px solid var(--mint);
  border-radius: 8px;
  background: var(--white);
  color: var(--plum);
  font-size: 11px;
  font-weight: 800;
}

.content-grid {
  display: grid;
  grid-template-columns: 150px 1fr;
  gap: 10px;
}

.accord {
  gap: 10px;
  min-height: 100px;
  padding: 12px;
  border-radius: 14px;
  background: var(--blush);
}

.scent-disc {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border-radius: 50%;
  background: var(--plum);
  color: var(--amber);
  font-size: 20px;
}

.accord figcaption {
  display: grid;
  gap: 4px;
}

.accord strong {
  font-size: 13px;
  line-height: 1.1;
}

.accord figcaption span {
  color: var(--plum);
  font-size: 11px;
  line-height: 1.25;
}

.ratio-panel {
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: 14px;
}

.ratio-panel h2 {
  margin: 0 0 7px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}

.notes {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.notes li {
  justify-content: space-between;
  font-size: 12px;
}

.notes li strong {
  color: var(--plum);
  font-size: 11px;
}

.note {
  padding: 3px 7px;
  border-radius: 5px;
  font-weight: 700;
}

.rose { background: var(--blush); }
.pear { background: var(--mint); }
.wood { background: var(--plum-soft); }

.card-footer {
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.maker {
  gap: 7px;
}

.maker-mark {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  border-radius: 8px;
  background: var(--amber);
  color: var(--ink);
  font-size: 12px;
  font-weight: 900;
}

.maker p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.maker strong {
  color: var(--ink);
}

button {
  gap: 8px;
  padding: 8px 10px;
  border: 0;
  border-radius: 9px;
  background: var(--ink);
  color: var(--white);
  font-size: 11px;
  font-weight: 800;
}

button span {
  color: var(--amber);
  font-size: 15px;
  line-height: 0;
}

